// The agents pane: a side pane (or, where none docks, a summary above the prompt) listing the subagents a
// session runs, what each is doing and what it costs in tokens, with each one's conversation a press away.
//
// From agentpane 1.1.4 by Anji Xu (https://github.com/xuanji86/claude-agentpane, MIT: see LICENSE-agentpane),
// as are live.tsx, lanes.tsx and time.ts. Changed here: a name column, the roster (an agent a row, in
// columns), `idle` read as done or waiting, a shared model said once, paths relative to the session, and
// this mod's own state keys. The command is /roster here, and one switch (`pane`) turns all of the pane off.
// This file also holds the two hooks naming shares with the pane, session.start and agent.spawn, since a
// plugin hooks an event once: naming's part of each is a call into names.ts. They are registered first and
// stay with the pane switched off; the pane's own hooks follow and do not.
//
// To bring a later agentpane in: the copy was taken at upstream commit 17be889 (1.1.4). Clone
// xuanji86/claude-agentpane, run `git diff 17be889 <new> -- hooks/ types/`, and apply it by hand: its
// hooks/register.tsx is this file, hooks/pane.test.tsx is tests/pane.test.tsx, hooks/agentpane.test.ts is
// tests/pane-logic.test.ts, and live.tsx, lanes.tsx, time.ts and types/index.d.ts keep their names. Its
// hooks/hooks.json is not used here, and its options are in .claude-plugin/plugin.json: diff that too. Then
// put the new commit in this note and in the README's Credits.
import { atom, read, update } from 'claude-code'
import type { AgentInfo, EngineInterface, Register, RenderChildren, RenderElement, SessionMessage, TurnUsage } from 'claude-code'

import type { AgentpaneAgent as Agent, AgentpaneLoop as Loop, AgentpaneTokens as Tokens } from '../types'
import { fmtDuration, laneRows } from './time'
import type { Lane } from './time'
import { NAMES_COMMAND, checkSpawn, namingOn, raise } from './names'
import type { Say } from './names'
import { withRunning } from './status'

const PANE = 'agents'
const TITLE = 'Agents'
// lazy: polls the engine's agent list every second, as no agent-status event reaches a mod; move to one if it lands.
const SYNC_MS = 1_000
const CONFIRM_MS = 5_000 // a pressed Stop waits this long for the press that confirms it
const SPAWN_GRACE_MS = 10_000 // a spawn the engine's list does not show yet stays this long
const LOOP_SHOWN_MS = 60_000 // a model loop no agent claims shows while it made a request this recently
const LOOP_KEPT_MS = 300_000 // and is forgotten after this long
const INLINE_ROWS = 8 // the pane above the prompt, where it cannot dock: a summary
const INLINE_READ_ROWS = 24 // and while it shows one conversation
const PROMPT_LINES = 4 // a prompt is the agent's brief: its head is enough
const PREVIEW_LINES = 3 // of a tool's result
const MAX_BLOCKS = 40 // of a conversation, drawn at most
// The engine refuses a tree with a text over 10,000 characters, or over 100,000 in all: stay well under.
const MAX_ARG = 300 // characters of a tool call's argument kept
const MAX_LINE = 500 // characters of one result line kept
const MAX_REPLY = 6_000 // characters of one reply drawn as Markdown
const TEXT_BUDGET = 60_000 // characters of a conversation drawn at once
const GROUP_BUDGET = 30_000 // characters of one opened run of tool calls: its newest calls
const GROUP_CALLS = 40 // and at most this many of them
const PREVIEW_SCAN = 8_192 // characters of a tool's result read for its preview
const MIN_ROWS = 3
const BATCH_GAP_MS = 60_000 // an agent started this long after the last one ended begins a new batch
const MAX_LANES = 8 // rows of the time axis
const DUR_COLS = 8 // a lane's clock, right-aligned
// The list is a roster: an agent a row, in columns. The right-hand ones go as the pane narrows.
const CLOCK_COLS = 7 // a row's clock, right-aligned: ' 1m 13s'
const TOOLS_COLS = 10 // '  12 tools', the numbers in line
const TOKENS_COLS = 8 // '   80.1k'
const WITH_TOKENS = 88 // columns of pane from which a row has its token count
const WITH_TOOLS = 72 // its tool count
const WITH_DOING = 56 // and what it is doing beside its task; narrower, that goes on a line beneath
const INLINE_MAX = 110 // columns of the summary above the prompt, so a row's clock stays beside its text

const agents = atom({ plugin: 'named-subagents-mod', key: 'agents' } as const, [])
const activity = atom({ plugin: 'named-subagents-mod', key: 'activity' } as const, {})
const viewing = atom({ plugin: 'named-subagents-mod', key: 'viewing' } as const, null)
const scrollTop = atom({ plugin: 'named-subagents-mod', key: 'scrollTop' } as const, null)
const rev = atom({ plugin: 'named-subagents-mod', key: 'rev' } as const, 0)
const expanded = atom({ plugin: 'named-subagents-mod', key: 'expanded' } as const, [])
const folded = atom({ plugin: 'named-subagents-mod', key: 'folded' } as const, false)
const tab = atom({ plugin: 'named-subagents-mod', key: 'tab' } as const, false)
const tokens = atom({ plugin: 'named-subagents-mod', key: 'tokens' } as const, {})
const loops = atom({ plugin: 'named-subagents-mod', key: 'loops' } as const, {})
const confirmStop = atom({ plugin: 'named-subagents-mod', key: 'confirmStop' } as const, null)
const hideDone = atom({ plugin: 'named-subagents-mod', key: 'hideDone' } as const, false)

// Colors are theme keys, so the pane follows the person's theme (dark, light, colorblind) as Claude Code's
// own rows do. The spinner and shimmer live in live.tsx, on the surface's frame clock.
const WIDE_SHARE = 0.62 // of the terminal, for the pane while it shows one agent's conversation
const MIN_WIDE = 60
const HANDLE_COLS = 2 // the hide handle's column, against the pane's left edge: its glyph and one space
const RIGHT_MARGIN = 1 // matches that one space on the right, so the content sits centred
// The handle: a tab several rows tall, each row of it a press target, so a click anywhere on it lands.
const HANDLE = ['╷ ', '│ ', '▸ ', '│ ', '╵ ']
const CLOSE_MARK_COLS = 3 // the engine draws its close mark over the end of the pane's first row
const BAND_RIGHT_PAD = 5 // clear of the engine's [-] band toggle at the band's top right

// The person's settings for the pane (`/config`, or pluginConfigs.named-subagents-mod.options in settings.json).
export type Config = { pane: boolean; autoOpen: boolean; foldAfterMs: number; motion: boolean; toasts: boolean; keepFinished: number; statusLine: boolean }
export const parseConfig = (options: unknown): Config => {
  const o = (options && typeof options === 'object' ? options : {}) as Record<string, unknown>
  const num = (v: unknown, d: number, lo: number, hi: number) => (typeof v === 'number' && Number.isFinite(v) ? Math.min(hi, Math.max(lo, Math.round(v))) : d)
  const bool = (v: unknown, d: boolean) => (typeof v === 'boolean' ? v : d)
  return {
    pane: bool(o.pane, true), // the one switch: off, the mod is names only
    autoOpen: bool(o.autoOpen, true),
    foldAfterMs: num(o.foldAfter, 10, 0, 3600) * 1000,
    motion: bool(o.motion, true),
    toasts: bool(o.toasts, true),
    keepFinished: num(o.keepFinished, 8, 1, 30),
    statusLine: bool(o.statusLine, true),
  }
}
let cfg = parseConfig(undefined) // set by register from the options it is given

// "claude-sonnet-5-5" -> "Sonnet 5.5", "claude-haiku-4-5-20251001" -> "Haiku 4.5"; anything else as given.
export const prettyModel = (id: string | undefined) => {
  if (!id) return ''
  const m = /^claude-([a-z]+)-(\d{1,2})(?:-(\d{1,2}))?(?:-\d{8})?(\[1m\])?$/.exec(id)
  if (!m) return id
  const [, family = '', major, minor, wide] = m
  return `${family.charAt(0).toUpperCase()}${family.slice(1)} ${major}${minor ? `.${minor}` : ''}${wide ? ' (1M)' : ''}`
}

// How hard it is asked to think, as its requests name it: 'high', or a number where the model takes a budget.
export const prettyEffort = (effort: string | number | undefined) =>
  effort === undefined || effort === '' ? '' : typeof effort === 'number' ? `effort ${effort}` : effort

// What an agent runs on, for a detail line: 'Opus 5.5 (1M) · high'.
export const runsOn = (a: { model?: string; effort?: string | number }) =>
  [prettyModel(a.model), prettyEffort(a.effort)].filter(Boolean).join(' · ')

// How a status reads and shows, wherever an agent's status is drawn.
export const look = (status: string): { word: string; mark: string; color?: string; dim?: boolean } =>
  status === 'running' ? { word: 'Running', mark: '✻', color: 'claude' }
  : status === 'completed' ? { word: 'Done', mark: '✓', color: 'success' }
  : status === 'failed' ? { word: 'Failed', mark: '✗', color: 'error' }
  : status === 'killed' ? { word: 'Stopped', mark: '⊘', dim: true }
  : status === 'idle' ? { word: 'Waiting', mark: '·', dim: true } // a teammate between turns
  : { word: status, mark: '·', dim: true }

// The emoji below U+1F300 that a terminal draws two columns wide ('✅', '⚡', '⭐'): a roster row is padded to the
// pane's width cell by cell, so each one miscounted pushes its row a column past the edge.
const WIDE_EMOJI = /[\u231a\u231b\u23e9-\u23ec\u23f0\u23f3\u25fd\u25fe\u2614\u2615\u2648-\u2653\u267f\u2693\u26a1\u26aa\u26ab\u26bd\u26be\u26c4\u26c5\u26ce\u26d4\u26ea\u26f2\u26f3\u26f5\u26fa\u26fd\u2705\u270a\u270b\u2728\u274c\u274e\u2753-\u2755\u2757\u2795-\u2797\u27b0\u27bf\u2b1b\u2b1c\u2b50\u2b55]/

// Terminal columns a string takes: East Asian wide and fullwidth characters and emoji take two; a skin tone
// colours the emoji before it and takes none.
// lazy: range table, not full Unicode East Asian Width; upgrade to a generated table if a script draws wrong.
export const cols = (s: string) => {
  let n = 0
  for (const ch of s) {
    const c = ch.codePointAt(0) ?? 0
    if (c >= 0x1f3fb && c <= 0x1f3ff) continue
    const wide = WIDE_EMOJI.test(ch) ||
      (c >= 0x1100 && c <= 0x115f) || (c >= 0x2e80 && c <= 0xa4cf) || (c >= 0xac00 && c <= 0xd7a3) ||
      (c >= 0xf900 && c <= 0xfaff) || (c >= 0xfe30 && c <= 0xfe4f) || (c >= 0xff00 && c <= 0xff60) ||
      (c >= 0xffe0 && c <= 0xffe6) || (c >= 0x1f300 && c <= 0x1faff) || (c >= 0x20000 && c <= 0x3fffd)
    n += wide ? 2 : 1
  }
  return n
}

// Cut text to `max` columns with an ellipsis.
export const fit = (s: string, max: number) => {
  if (cols(s) <= max) return s
  let out = ''
  let n = 1
  for (const ch of s) {
    if (n + cols(ch) > max) break
    n += cols(ch)
    out += ch
  }
  return `${out}…`
}

// Text from the agents' transcripts: no control, escape or bidi characters; tabs as spaces; reminders the
// engine injected left out.
const UNSAFE = /[\u0000-\u0008\u000b-\u001f\u007f-\u009f\u061c\u200b-\u200f\u2028-\u202e\u2060-\u2069\ufeff]/g
export const clean = (s: string) =>
  s.replace(/<system-reminder>[\s\S]*?<\/system-reminder>/g, '').replace(/\t/g, '  ').replace(UNSAFE, '').trim()
const oneLine = (s: string) => clean(s).replace(/\s+/g, ' ')

// Word-wrap to `width` columns; a word longer than a line is cut where the line ends.
export const wrap = (text: string, width: number): string[] => {
  const w = Math.max(8, width)
  const out: string[] = []
  for (const para of text.split('\n')) {
    let line = ''
    let n = 0
    for (const ch of para) {
      if (n + cols(ch) > w) {
        const cut = line.lastIndexOf(' ')
        if (cut > 0 && cut >= line.length / 2) {
          out.push(line.slice(0, cut))
          line = line.slice(cut + 1)
        } else {
          out.push(line)
          line = ''
        }
        n = cols(line)
      }
      line += ch
      n += cols(ch)
    }
    out.push(line.trimEnd())
  }
  return out
}

// The session's directory, from session.start. A path under it is drawn as the person would type it there.
let root = ''
export const setRoot = (cwd: string) => {
  const dir = cwd.replace(/\/+$/, '')
  root = dir.length > 1 ? dir : ''
}
// Pure: `text` with each path under `cwd` made relative ("/w/src/a.ts" -> "src/a.ts", "/w" -> "."). Only a
// path that starts a word (after a space, an opening quote, `=`, `(` or a shell mark) and is the directory
// itself or inside it. Left as written: a sibling ("/w-old", "/w (copy)"), a remote or mounted path
// ("host:/w/x", "-v /w:/w"), one glued to a variable ("$D/w") and a URL.
export const relative = (text: string, cwd = root) => {
  if (!cwd) return text
  let out = ''
  let from = 0
  for (let at = text.indexOf(cwd); at !== -1; at = text.indexOf(cwd, from)) {
    const before = at ? text[at - 1]! : ' '
    const quote = before === '"' || before === "'" ? before : ''
    // A quote opens only at the start of a word: in `"$D"/w/x` it closes one.
    const opens = quote ? at < 2 || /[\s=(]/.test(text[at - 2]!) : /[\s`=(<>|&;]/.test(before)
    const rest = text.slice(at + cwd.length, at + cwd.length + 2)
    const inside = /^\/[^\s"'`)/]/.test(rest)
    // The directory itself: to the closing quote when quoted, else to a space or a shell mark.
    const itself = quote ? rest.replace(/^\//, '').startsWith(quote) : /^\/?(?:$|[\s`);|&<>])/.test(rest)
    out += text.slice(from, at)
    from = at + cwd.length
    if (opens && inside) from += 1 // drop "cwd/"
    else if (opens && itself) (out += '.'), (from += rest.startsWith('/') ? 1 : 0)
    else out += cwd
  }
  return out + text.slice(from)
}

// A tool call in Claude Code's words: "Bash(npm test)", "Read(register.tsx)", "github:list_issues".
export const toolParts = (tool: string, input: Record<string, unknown>) => {
  const s = (k: string) => (typeof input[k] === 'string' ? (input[k] as string) : '')
  const base = (p: string) => p.split(/[\\/]/).pop() ?? p
  const arg =
    tool === 'Bash' ? s('command')
    : ['Read', 'Write', 'Edit', 'NotebookEdit'].includes(tool) ? base(s('file_path') || s('notebook_path'))
    : tool === 'Grep' || tool === 'Glob' ? s('pattern')
    : tool === 'WebFetch' ? s('url')
    : tool === 'WebSearch' ? s('query')
    : tool === 'Agent' ? s('description')
    : tool === 'Skill' ? s('skill')
    : ''
  const name = oneLine(tool) // as its argument is: a name is the API's to check, and the pane draws it anyway
  return { name: name.startsWith('mcp__') ? name.split('__').slice(1).join(':') : name, arg: fit(oneLine(relative(arg)), MAX_ARG) }
}
export const describeTool = (tool: string, input: Record<string, unknown>) => {
  const { name, arg } = toolParts(tool, input)
  return arg ? `${name}(${arg})` : name
}

// The engine's list over what the pane knew: when each was first seen, and when it was first seen done.
export const mergeAgents = (before: readonly Agent[], list: readonly AgentInfo[], now: number): Agent[] => {
  const prev = new Map(before.map(a => [a.id, a]))
  const listed = new Set(list.map(a => a.id))
  // A spawn the hook recorded that the engine's list does not show yet: kept a moment, not dropped.
  const pending = before.filter(a => !listed.has(a.id) && a.status === 'running' && now - a.firstSeen < SPAWN_GRACE_MS)
  const merged = list.map(info => {
    const old = prev.get(info.id)
    // Between turns ('idle') a background agent has given its answer: to the person it is done. A message to
    // it wakes it as 'running', a new run. A teammate between turns waits for its next message: that stays 'idle'.
    const status = info.status === 'idle' && !info.teammateId ? 'completed' : info.status
    const running = status === 'running'
    const seenRunning = (old?.seenRunning ?? false) || running
    const endedAt = running ? undefined : (old?.endedAt ?? (seenRunning ? now : undefined))
    const resumed = running && old?.endedAt !== undefined // ended, then sent a message: a new run from now
    return {
      id: info.id, description: info.description, type: info.type, status,
      ...(info.name && { name: info.name }), ...(info.parentId && { parentId: info.parentId }),
      firstSeen: resumed ? now : (old?.firstSeen ?? now), seenRunning, ...(endedAt !== undefined && { endedAt }),
      ...(old?.model && { model: old.model }), ...(old?.effort !== undefined && { effort: old.effort }),
    }
  })
  return [...merged, ...pending]
}

// A spawn as the pane records it the moment it starts, before the engine's list shows it.
export const spawned = (list: readonly Agent[], a: Agent): Agent[] =>
  list.some(x => x.id === a.id) ? list.map(x => (x.id === a.id ? { ...x, model: a.model ?? x.model } : x)) : [...list, a]

// A model loop no agent claims, one more request.
export const stepLoop = (all: Readonly<Record<string, Loop>>, id: string, now: number): Record<string, Loop> => {
  const old = all[id]
  return { ...all, [id]: { firstSeen: old?.firstSeen ?? now, lastSeen: now, requests: (old?.requests ?? 0) + 1 } }
}

// What the list shows: every running agent and the most recently finished ones, in the engine's order.
export const visibleAgents = (all: readonly Agent[], keep = 8): Agent[] => {
  const ended = (a: Agent, i: number) => [a.endedAt ?? a.firstSeen, i] as const
  const recent = all
    .map((a, i) => ({ a, key: ended(a, i) }))
    .filter(({ a }) => a.status !== 'running')
    .sort((x, y) => y.key[0] - x.key[0] || y.key[1] - x.key[1])
    .slice(0, keep)
    .map(({ a }) => a)
  return all.filter(a => a.status === 'running' || recent.includes(a))
}

// Pure: the list as groups, each agent whose parent is not listed heading one with its descendants under
// it; running groups first. With `onlyRunning`, finished agents are left out and their running children
// head groups of their own.
export const arrange = (shown: readonly Agent[], onlyRunning = false) => {
  const list = onlyRunning ? shown.filter(a => a.status === 'running') : shown
  const ids = new Set(list.map(a => a.id))
  const under = (id: string) => {
    const out: { agent: Agent; depth: number }[] = []
    const walk = (parent: string, depth: number) => {
      if (depth > 3) return // a loop in the parents, or a tree deeper than the pane can indent
      for (const a of list) if (a.parentId === parent) out.push({ agent: a, depth }), walk(a.id, depth + 1)
    }
    walk(id, 1)
    return out
  }
  const tops = list.filter(a => !a.parentId || !ids.has(a.parentId)).map(a => ({ agent: a, kids: under(a.id) }))
  return { running: tops.filter(t => t.agent.status === 'running'), finished: tops.filter(t => t.agent.status !== 'running') }
}

const elapsed = (a: Agent, now: number) => (a.seenRunning ? fmtDuration((a.endedAt ?? now) - a.firstSeen) : '')

// One response's usage added to an agent's tally; `context` is what its latest request carried.
export const addUsage = (
  t: Tokens | undefined,
  u: Pick<TurnUsage, 'input_tokens' | 'output_tokens' | 'cache_read_input_tokens' | 'cache_creation_input_tokens'>,
  stopReason: string | null = null,
): Tokens => {
  const input = u.input_tokens + u.cache_read_input_tokens + u.cache_creation_input_tokens
  const truncated = (t?.truncated ?? 0) + (stopReason === 'max_tokens' ? 1 : 0)
  return {
    ...(truncated && { truncated }),
    input: (t?.input ?? 0) + input,
    cached: (t?.cached ?? 0) + u.cache_read_input_tokens,
    output: (t?.output ?? 0) + u.output_tokens,
    context: input + u.output_tokens,
    requests: (t?.requests ?? 0) + 1,
  }
}

// "950", "12.3k", "312k", "1.2M".
export const fmtTokens = (n: number) =>
  n < 1000 ? String(n) : n < 99_950 ? `${+(n / 1000).toFixed(1)}k` : n < 999_500 ? `${Math.round(n / 1000)}k` : `${+(n / 1_000_000).toFixed(1)}M`

export type CallState = 'running' | 'ok' | 'error' | 'stopped'
export type Call = { id: string; name: string; arg: string; state: CallState; result: string[]; more: number }
export type Block =
  | { kind: 'prompt'; text: string }
  | { kind: 'reply'; text: string }
  | { kind: 'tools'; key: string; calls: Call[] }
const STATE_COLOR: Record<CallState, string> = { running: 'claude', ok: 'success', error: 'error', stopped: 'inactive' }

// A tool's result as its first lines, each cut to length, and how many more it had.
// Only the head is cleaned and split; the rest, often megabytes, is counted by its newlines.
export const preview = (text: string) => {
  const lines = clean(text.slice(0, PREVIEW_SCAN)).split('\n').map(l => l.trimEnd()).filter(l => l.trim())
  let rest = 0 // lazy: counts blank lines past the head too; exact would need the whole text split
  for (let i = text.indexOf('\n', PREVIEW_SCAN); i !== -1; i = text.indexOf('\n', i + 1)) rest++
  return { result: lines.slice(0, PREVIEW_LINES).map(l => fit(l, MAX_LINE)), more: Math.max(0, lines.length - PREVIEW_LINES) + rest }
}

// Pure: an agent's conversation as blocks: its brief (and any later message to it), each reply, and each
// run of tool calls between them as one group. A call left unanswered by an agent that `ended` was cut off.
export const transcriptBlocks = (msgs: readonly SessionMessage[], ended = false): Block[] => {
  const out: Block[] = []
  for (const m of msgs) {
    const text = clean(m.text)
    if (m.role === 'user') {
      if (text) out.push({ kind: 'prompt', text })
      continue
    }
    if (text) out.push({ kind: 'reply', text })
    for (const use of m.toolUses) {
      const { name, arg } = toolParts(use.tool, use.input)
      const state: CallState = use.text === undefined ? (ended ? 'stopped' : 'running') : use.isError ? 'error' : 'ok'
      const call: Call = { id: use.tool_use_id, name, arg, state, ...(use.text === undefined ? { result: [], more: 0 } : preview(use.text)) }
      const last = out[out.length - 1]
      if (last?.kind === 'tools') last.calls.push(call)
      else out.push({ kind: 'tools', key: use.tool_use_id, calls: [call] })
    }
  }
  return out
}

// Pure: the blocks to draw, within MAX_BLOCKS and the text budget: from `top` down when scrolled back, the
// newest otherwise. Always at least one.
export const pickBlocks = (blocks: readonly Block[], top: number | null) => {
  const size = (b: Block) =>
    b.kind === 'tools' ? b.calls.reduce((n, c) => n + c.arg.length + c.result.join('').length + 40, 0) : Math.min(b.text.length, MAX_REPLY) + 40
  const out: Block[] = []
  let used = 0
  const take = (b: Block | undefined, add: (b: Block) => void) => {
    if (!b || out.length >= MAX_BLOCKS) return false
    used += size(b)
    if (used > TEXT_BUDGET && out.length) return false
    add(b)
    return true
  }
  if (top === null) for (let i = blocks.length - 1; take(blocks[i], b => out.unshift(b)); i--);
  else for (let i = Math.max(0, top); take(blocks[i], b => out.push(b)); i++);
  return out
}

// Pure: the newest calls of an opened run that fit GROUP_BUDGET and GROUP_CALLS (always one), and how many
// earlier ones are left out: an agent that only calls tools makes one run of hundreds.
export const lastCalls = (calls: readonly Call[]) => {
  let used = 0
  let from = calls.length
  while (from > 0 && calls.length - from < GROUP_CALLS) {
    const c = calls[from - 1]!
    used += c.arg.length + c.result.join('').length + 40
    if (used > GROUP_BUDGET && from < calls.length) break
    from--
  }
  return { shown: calls.slice(from), hidden: from }
}

// A run of tool calls in Claude Code's words: "Read 3 files, ran 2 commands".
const VERBS: Record<string, [string, string, string]> = {
  Read: ['read', 'file', 'files'], Bash: ['ran', 'command', 'commands'], Edit: ['edited', 'file', 'files'],
  Write: ['wrote', 'file', 'files'], NotebookEdit: ['edited', 'notebook', 'notebooks'], Grep: ['searched for', 'pattern', 'patterns'],
  Glob: ['searched for', 'pattern', 'patterns'], WebFetch: ['fetched', 'page', 'pages'], WebSearch: ['searched the web', 'time', 'times'],
  Agent: ['ran', 'agent', 'agents'],
}
export const groupSummary = (calls: readonly Call[]) => {
  const counts = new Map<string, number>()
  for (const c of calls) counts.set(c.name, (counts.get(c.name) ?? 0) + 1)
  const parts = [...counts].map(([name, n]) => {
    const verb = VERBS[name]
    return verb ? `${verb[0]} ${n} ${n === 1 ? verb[1] : verb[2]}` : `called ${name}${n > 1 ? ` ${n} times` : ''}`
  })
  const text = parts.join(', ')
  return text.charAt(0).toUpperCase() + text.slice(1)
}
const groupState = (calls: readonly Call[]): CallState =>
  calls.some(c => c.state === 'running') ? 'running'
  : calls.some(c => c.state === 'error') ? 'error'
  : calls.some(c => c.state === 'stopped') ? 'stopped'
  : 'ok'

// The name an agent was given (its Agent call's `name`, or one a naming mod set), cleaned and cut; '' when none.
export const givenName = (a: Pick<Agent, 'name'>, max = 16) => (a.name ? fit(oneLine(a.name), max) : '')
// The type an agent has when its call names none: a named agent's conversation header leaves it out.
const DEFAULT_TYPE = 'general-purpose'
// An agent's task: beside a given name its description alone (its type shows in its conversation's header); without
// a name, as Claude Code draws an Agent call, type and description. Cleaned and cut.
const taskOf = (a: Agent, max = 60) =>
  givenName(a) ? fit(oneLine(a.description || a.type), max) : `${fit(oneLine(a.type), 30)}(${fit(oneLine(a.description || a.type), max)})`
// An agent as the pane's toasts and its Stop say it: its name when it was given one, then its task.
export const nameOf = (a: Agent, max = 60) => [givenName(a), taskOf(a, max)].filter(Boolean).join(' ')
// The list's name column: each name padded to the widest shown, and a gap; '' on every row when no agent has one.
export const nameColumn = (shown: readonly Agent[]) => {
  const width = Math.max(0, ...shown.map(a => cols(givenName(a))))
  // An agent the column was not built from (one off the list, still in the batch) may be wider than it.
  return (a: Agent) => (width ? givenName(a) + ' '.repeat(Math.max(0, width - cols(givenName(a))) + 2) : '')
}

// Pure: a roster row's columns in a pane `width` wide, after its mark: the name (`nameCols` where it fits,
// less where the task would have under 8 columns), the task, what the agent is doing (0: none), its tool count
// and its tokens (0: left out). The task takes what the longest one shown needs (`taskCols`), up to three
// fifths of the room it shares with the doing. `beneath`: a narrow pane has a line under a row for what the
// agent is doing, so the column goes; without one (the summary above the prompt) it stays while it has 8 columns.
const MIN_TASK = 8
export const rosterColumns = (width: number, nameCols: number, taskCols: number, beneath = true) => {
  const tokens = width >= WITH_TOKENS ? TOKENS_COLS : 0
  const tools = width >= WITH_TOOLS ? TOOLS_COLS : 0
  const name = Math.max(0, Math.min(nameCols, width - 2 - CLOCK_COLS - tools - tokens - MIN_TASK))
  const rest = Math.max(MIN_TASK, width - 2 - name - CLOCK_COLS - tools - tokens)
  const task = Math.max(MIN_TASK, Math.min(taskCols + 2, Math.floor(rest * 0.6)))
  const doing = (beneath ? width >= WITH_DOING : rest - task >= MIN_TASK) ? rest - task : 0
  return { name, task: rest - doing, doing, tools, tokens }
}

// Pure: what every agent shown runs on, when they all run on the same ('Haiku 4.5 · high'): said once, in
// the header. '' when they differ or none is known yet; each row then says its own.
export const sharedModel = (shown: readonly Pick<Agent, 'model' | 'effort'>[]) => {
  const known = [...new Set(shown.map(runsOn).filter(Boolean))]
  return known.length === 1 ? known[0]! : ''
}

// Pure: the toast for agents that finished since the last look, or null when none did.
export const finishNotice = (before: readonly Agent[], after: readonly Agent[], now: number) => {
  const ended = after.filter(a => a.status !== 'running' && before.some(b => b.id === a.id && b.status === 'running'))
  if (!ended.length) return null
  if (ended.length === 1) {
    const a = ended[0]!
    const l = look(a.status)
    const t = elapsed(a, now)
    // By its name when it was given one, its task after; without one the task is all there is to call it.
    const given = givenName(a)
    return `${l.mark} ${given || taskOf(a, 40)} ${l.word.toLowerCase()}${t ? ` · ${t}` : ''}${given ? ` · ${taskOf(a, 40)}` : ''}`
  }
  const failed = ended.filter(a => a.status === 'failed').length
  return `✓ ${ended.length} agents finished${failed ? ` · ✗ ${failed} failed` : ''}`
}

const uses = (n: number) => `${n} tool use${n === 1 ? '' : 's'}`

// Pure: the latest batch, oldest first: the agents that ran, back from the newest to a start more than
// BATCH_GAP_MS after everything before it had ended.
export const latestBatch = (all: readonly Agent[]): Agent[] => {
  const ran = all.filter(a => a.seenRunning).sort((x, y) => x.firstSeen - y.firstSeen)
  let start = 0
  let reach = -Infinity // when the agents so far had all ended; never, while one runs
  ran.forEach((a, i) => {
    if (a.firstSeen > reach + BATCH_GAP_MS) start = i
    reach = Math.max(reach, a.status === 'running' ? Infinity : (a.endedAt ?? a.firstSeen))
  })
  return ran.slice(start)
}

// Pure: what a batch of two or more came to, once none of it runs: how long it took, how much agent time
// that was and so how much ran side by side, and what it used.
export const batchReceipt = (
  batch: readonly Agent[],
  act: Readonly<Record<string, { tools: number }>>,
  tok: Readonly<Record<string, Tokens>>,
) => {
  if (batch.length < 2 || batch.some(a => a.status === 'running')) return null
  const end = (a: Agent) => a.endedAt ?? a.firstSeen
  const wall = Math.max(...batch.map(end)) - Math.min(...batch.map(a => a.firstSeen))
  // An agent's subagents run inside its own time: only the agents at the top of the batch add to it.
  const work = batch.filter(a => !batch.some(p => p.id === a.parentId)).reduce((n, a) => n + end(a) - a.firstSeen, 0)
  const count = (s: string) => batch.filter(a => a.status === s).length
  const tools = batch.reduce((n, a) => n + (act[a.id]?.tools ?? 0), 0)
  const used = batch.reduce((n, a) => n + (tok[a.id] ? tok[a.id]!.input + tok[a.id]!.output : 0), 0)
  const together = wall > 0 ? work / wall : 1
  const who = [...new Set(['completed', 'failed', 'killed', ...batch.map(a => a.status)])]
    .map(s => (count(s) ? `${count(s)} ${look(s).word.toLowerCase()}` : '')).filter(Boolean).join(' · ')
  return {
    failed: count('failed') > 0,
    text: [
      `${who} in ${fmtDuration(wall)}`,
      `${fmtDuration(work)} of agent time${together >= 1.2 ? ` (${together.toFixed(1)}× in parallel)` : ''}`,
      tools ? uses(tools) : '',
      used ? `${fmtTokens(used)} tokens` : '',
    ].filter(Boolean).join(' · '),
  }
}

// Pure: the status line under the prompt while a batch runs, or undefined to clear it.
export const statusOf = (batch: readonly Agent[]) => {
  const running = batch.filter(a => a.status === 'running').length
  if (!running) return undefined
  const failed = batch.filter(a => a.status === 'failed').length
  const of = running === batch.length ? `${running} agent${running === 1 ? '' : 's'} running` : `${running} of ${batch.length} agents running`
  return `${look('running').mark} ${of}${failed ? ` · ${look('failed').mark} ${failed} failed` : ''}`
}

// Module state that nothing draws from (a reload resets it to "nothing opened yet").
let autoOpened = false // the mod opened the pane unasked, rather than the person
let closedByPerson = false // closed by hand while agents ran: stays shut until a new one starts
let foldingAway = false // the close under way is a fold: the tab above the prompt brings the pane back
let foldWhenIdle = false // agents ran while the pane was open: fold it once they are all done
let isFullscreen: boolean | undefined // from the last drawing: only the fullscreen layout docks a pane
let lastPlacement: string | null = null
let lastColumns = 0 // the terminal's width, from the last drawing
let lastRunningAt = 0
let armedAt = 0 // when Stop was pressed once
// The status line as last set, so it is set only when it changes; null: not yet by this module, so a line a
// reload left behind is cleared on the first sync.
let lastStatus: string | undefined | null = null
let viewingId: string | null = null // the conversation on screen, for the events that redraw it
let transcript = { key: '', blocks: [] as Block[] } // that conversation's blocks, read once per change
// lazy: one sync at a time by a module flag; a slow agent.list only skips ticks.
let syncing = false
// Agents the spawn hook listed since the last sync: new to the pane, though the list already holds them.
const spawnedSinceSync = new Set<string>()

// Never rejects. Keeps the list current, opens the pane when an agent starts, folds it once they are done.
async function sync($: EngineInterface) {
  if (syncing) return
  syncing = true
  try {
    const now = await $.clock.now()
    // The desktop app has its own agents view: with no terminal drawing, nothing opens or shows unasked there.
    const surfaces = await $.session.surfaces().catch(() => [])
    const quiet = surfaces.includes('desktop') && !surfaces.includes('terminal')
    const info = await $.agent.list()
    const before = await read($, agents)
    let list = mergeAgents(before, info, now)
    // Written over the list as it stands then, so an agent the spawn hook records meanwhile keeps its model.
    if (JSON.stringify(list) !== JSON.stringify(before)) list = await update($, agents, cur => mergeAgents(cur, info, now))
    const notice = finishNotice(before, list, now)
    if (notice && cfg.toasts && !quiet) $.ui.toast(notice)
    const ids = new Set(list.map(a => a.id))
    if (Object.keys(await read($, activity)).some(id => !ids.has(id)))
      await update($, activity, m => Object.fromEntries(Object.entries(m).filter(([id]) => ids.has(id))))

    const running = list.filter(a => a.status === 'running')
    const pane = (await $.ui.panes()).find(p => p.id === PANE)
    // A new agent unfolds the pane, whoever folded or closed it, and shows the list.
    const fresh = running.some(a => spawnedSinceSync.has(a.id) || !before.some(b => b.id === a.id))
    for (const a of list) spawnedSinceSync.delete(a.id) // a spawn recorded after this list was read waits for the next
    if (fresh) {
      closedByPerson = false
      // With autoOpen off the pane stays shut, and a fold the person made keeps its tab.
      if (!pane && cfg.autoOpen) await showList($, { clearFold: true })
    }
    // The conversation on screen belongs to an agent no longer listed (/clear): back to the list, so it can fold.
    const open = await read($, viewing)
    if (open && !ids.has(open)) await showList($)
    if (running.length) lastRunningAt = now
    if (pane && running.length) foldWhenIdle = true
    if (!pane && running.length && cfg.autoOpen && !quiet && !closedByPerson && !(await read($, folded))) {
      autoOpened = true
      await openPane($, 'list') // docked beside a fullscreen transcript, else the summary above the prompt
    } else if (
      pane && foldWhenIdle && !running.length && cfg.foldAfterMs > 0 && now - lastRunningAt >= cfg.foldAfterMs &&
      !pane.isFocused && !(await read($, viewing))
    ) {
      await foldAway($) // all done; not while the person reads a conversation
    }
    // Folded, the tab above the prompt stands in for the pane while the session has agents to show.
    const showTab = (await read($, folded)) && list.length > 0
    if (showTab !== (await read($, tab))) await update($, tab, () => showTab)
    if ((await read($, confirmStop)) && now - armedAt > CONFIRM_MS) await update($, confirmStop, () => null)

    // Loops that turned out to be agents, or went quiet long ago, are forgotten; tokens of neither go too.
    const loopsNow = await read($, loops)
    const keptLoops = Object.fromEntries(Object.entries(loopsNow).filter(([id, l]) => !ids.has(id) && now - l.lastSeen < LOOP_KEPT_MS))
    if (Object.keys(keptLoops).length !== Object.keys(loopsNow).length) await update($, loops, () => keptLoops)
    const kept = (id: string) => ids.has(id) || id in keptLoops
    if (Object.keys(await read($, tokens)).some(id => !kept(id)))
      await update($, tokens, m => Object.fromEntries(Object.entries(m).filter(([id]) => kept(id))))

    // Under the prompt while a batch runs and the pane is not on screen (folded, closed, or waiting for room).
    const placed = cfg.statusLine && (await $.ui.panes()).some(p => p.id === PANE && p.isPlaced && p.isShown)
    const status = cfg.statusLine && !placed && !quiet ? statusOf(latestBatch(list)) : undefined
    if (status !== lastStatus) {
      lastStatus = status
      $.ui.status(withRunning(status)) // the line is naming's too: its alarm stands until it clears
    }
  } catch {
    // the next tick tries again
  } finally {
    syncing = false
  }
}

// Back to the list, live, nothing armed; `clearFold` also clears the fold.
async function showList($: EngineInterface, { clearFold = false } = {}) {
  await update($, viewing, () => null)
  await update($, scrollTop, () => null)
  await update($, expanded, () => [])
  await update($, confirmStop, () => null)
  if (clearFold) await update($, folded, () => false)
}

// The pane sized for what it shows: docked, at its usual width or widened to read a conversation; above the
// prompt, a summary's rows or a conversation's. `focus` asks for the keyboard (granted over an empty
// composer), so the conversation's b/k/j keys work.
async function openPane($: EngineInterface, view: 'list' | 'conversation', focus = false) {
  const docked = lastPlacement ? lastPlacement === 'dock' : isFullscreen !== false
  const columns = docked && view === 'conversation' && lastColumns ? Math.max(MIN_WIDE, Math.round(lastColumns * WIDE_SHARE)) : undefined
  const rows = docked ? undefined : view === 'conversation' ? INLINE_READ_ROWS : INLINE_ROWS
  await $.ui.open({ id: PANE, title: TITLE, ...(columns && { columns }), ...(rows && { rows }), ...(focus && { focus: true as const }) })
}

// Fold: the pane closes, so the transcript has the width back, and a tab above the prompt reopens it.
async function foldAway($: EngineInterface) {
  await update($, folded, () => true)
  await update($, tab, () => true)
  foldingAway = true
  try {
    await $.ui.close({ id: PANE })
  } finally {
    foldingAway = false
  }
}

// The person unfolds it from the tab: theirs now, so it folds again only after agents run in it.
async function unfold($: EngineInterface) {
  await update($, folded, () => false)
  await update($, tab, () => false)
  closedByPerson = false
  autoOpened = false
  foldWhenIdle = (await read($, agents)).some(a => a.status === 'running')
  await openPane($, (await read($, viewing)) ? 'conversation' : 'list')
}

// The pane is switched off. Flipped mid-session, the reload finds what the pane left: its count under the
// prompt, the pane itself if open, and its list, fold and open conversation in the session's state. All
// three go, so switching it on again starts clean (an agent that finished meanwhile would else be announced
// then, with the whole time off as its run). A session that starts with the pane off has none of them, and
// nothing is closed or written. Never rejects.
async function putAway($: EngineInterface) {
  try {
    // The whole line: a reload has already forgotten naming's alarm (status.ts), as it does with the pane on.
    $.ui.status(withRunning(undefined))
    if ((await $.ui.panes()).some(p => p.id === PANE)) await $.ui.close({ id: PANE })
    if ((await read($, agents)).length || (await read($, folded)) || (await read($, tab)) || (await read($, viewing))) {
      await update($, agents, () => [])
      await update($, tab, () => false)
      await showList($, { clearFold: true })
    }
  } catch { // audit-allow: fail-loud — a pane that could not be closed is on screen, which says so itself
  }
}

// Stop a running agent with Claude Code's own TaskStop, on the person's confirmed press of Stop.
async function stopAgent($: EngineInterface, a: Agent) {
  const name = nameOf(a)
  const done = (await $.tool
    // The consent reads to the engine as the person's words: the type and id, never the description a model wrote.
    .call({ tool: 'TaskStop', task_id: a.id, consent: `The user pressed "Stop" on the ${JSON.stringify(fit(oneLine(a.type), 30))} agent ${fit(a.id, 40)} in the agents pane` } as never)
    .catch((err: unknown) => ({ deny: String(err) }))) as { deny?: string; isError?: boolean; text?: string }
  const why = done.deny || (done.isError ? oneLine(String(done.text ?? '')) || 'the tool reported an error' : '')
  if (why) $.ui.toast(`Could not stop ${name}: ${fit(oneLine(why), 120)}`)
}

// The conversation on screen changed: draw it again.
const redraw = ($: EngineInterface, agentId: string | undefined) => {
  if (agentId && agentId === viewingId) void update($, rev, n => n + 1).catch(() => undefined)
}

// Naming's alarm, for its part of the two shared hooks: a toast and the status line.
const sayOf = ($: EngineInterface): Say => ({ toast: line => $.ui.toast(line, { timeoutMs: 10000 }), status: line => $.ui.status(line) })

export const register: Register = (on, options) => {
  cfg = parseConfig(options)
  const naming = namingOn(options)

  on('session.start', async ($, e, next) => {
    setRoot(e.cwd)
    if (naming) await Promise.resolve($.command.register(NAMES_COMMAND)).catch(() => raise(sayOf($), 'could not register /names'))
    if (!cfg.pane) {
      void putAway($) // not awaited: a session start does not wait on the pane's leftovers
      return next(e)
    }
    $.clock.every(SYNC_MS, () => void sync($)) // before the command: without it the pane still lists, counts and opens
    await Promise.resolve($.command.register({ name: 'roster', description: 'Show or hide the pane of running agents' }))
      .catch(() => raise(sayOf($), 'could not register /roster'))
    return next(e)
  })

  // An agent is listed the moment it starts, with the model it runs on, ahead of the next poll.
  on('agent.spawn', async ($, e, next) => {
    const started = await next(e)
    const id = started.agentId
    // Naming's check that the name it drew for this call is the one the agent got. First, and it never
    // throws: nothing the pane does below can skip it.
    if (naming) await checkSpawn(sayOf($), () => $.agent.list(), e, id)
    if (cfg.pane && id && !started.deny) {
      const a: Agent = {
        id, description: e.description, type: e.subagentType, status: 'running',
        ...(e.parentAgentId && { parentId: e.parentAgentId }), ...(e.name && { name: e.name }),
        firstSeen: await $.clock.now(), seenRunning: true, ...(started.model && { model: started.model }),
      }
      spawnedSinceSync.add(id)
      void update($, agents, list => spawned(list, a)).catch(() => undefined)
    }
    return started
  }).catch(($, e, next) => next(e)) // replays the spawn if it already ran; never refuses one

  // The pane switched off: the two hooks above are naming's too and stay; none of the pane's own below.
  // A session cannot take a command back, so a /roster registered before the switch was flipped is still
  // offered until the session ends: it says why nothing opens.
  if (!cfg.pane) {
    on('command.run', { command: 'roster' }, async () => ({ text: 'The agents pane is switched off. "Show the agents pane" in /config turns it on.' }))
    return
  }

  on('command.run', { command: 'roster' }, async $ => {
    const pane = (await $.ui.panes()).find(p => p.id === PANE)
    if (pane?.isPlaced) {
      await $.ui.close({ id: PANE })
      return { text: 'Agents pane closed.' }
    }
    autoOpened = false // opened by hand: the mod leaves it open
    closedByPerson = false
    foldWhenIdle = false
    await update($, folded, () => false)
    await update($, tab, () => false)
    await openPane($, 'list', true) // asked for, so placed even where an unasked pane waits
    return { text: 'Agents pane opened.' }
  })

  on('ui.close', async ($, e, next) => {
    const result = await next(e)
    if (e.id === PANE && !('deny' in result && result.deny)) {
      foldWhenIdle = false
      autoOpened = false
      await update($, confirmStop, () => null)
      if (!foldingAway) {
        // closed by hand (its close mark, Esc, ctrl+x x, /roster) while agents run: stays shut until a new one starts
        closedByPerson = (await read($, agents)).some(a => a.status === 'running')
        await update($, viewing, () => null)
      }
    }
    return result
  })

  // What each agent is doing: its latest tool call; and its conversation, if on screen, grows.
  on('tool.call', async ($, e, next) => {
    const id = e.agentId
    if (id) {
      const text = describeTool(e.tool, e as unknown as Record<string, unknown>)
      void update($, activity, m => ({ ...m, [id]: { text, tools: (m[id]?.tools ?? 0) + 1 } })).catch(() => undefined)
      redraw($, id)
    }
    const result = await next(e)
    redraw($, id)
    return result
  })

  // What each agent's responses cost, as the API reported each one; a response grows its conversation. A
  // loop no listed agent claims (a workflow's agent, a compaction or memory fork) is counted on its own.
  on('turn.step', async function* ($, e, next) {
    const result = yield* next(e)
    const id = e.agentId
    if (id) {
      const usage = result?.usage
      if (usage) void update($, tokens, m => ({ ...m, [id]: addUsage(m[id], usage, result.stopReason) })).catch(() => undefined)
      const listed = (await read($, agents)).find(a => a.id === id)
      // The model and effort its requests name, as the engine resolved them: an agent whose spawn named no model (a
      // forked skill, an inherited model) still shows what it runs on, and an alias the spawn gave ('sonnet') reads as
      // the real id. Effort is the step's alone (a spawn reports none); absent for a model without it.
      if (listed && ((e.model && listed.model !== e.model) || listed.effort !== e.effort)) {
        const ran = { ...(e.model && { model: e.model }), effort: e.effort }
        void update($, agents, l => l.map(a => (a.id === id ? { ...a, ...ran } : a))).catch(() => undefined)
      }
      if (!listed) {
        const now = await $.clock.now()
        void update($, loops, l => stepLoop(l, id, now)).catch(() => undefined)
      }
    }
    redraw($, id)
    return result
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const els = $.ui.resolve(e)
    const { Box, Button, Markdown, Text } = els
    // Live lines run on the surface's own frame clock where it has one (terminal, desktop); elsewhere they are
    // static. Every surface's table names Client, but on the others it draws nothing: ask by surface.
    const Client = (e.surface === 'terminal' || e.surface === 'desktop') && 'Client' in els ? els.Client : null
    lastPlacement = e.props.placement
    lastColumns = e.viewport?.columns ?? lastColumns
    isFullscreen = e.viewport?.isFullscreen ?? isFullscreen
    const inline = e.props.placement === 'inline' // above the prompt: a summary, no handle
    const W = Math.max(22, e.props.bodyColumns - (inline ? 0 : HANDLE_COLS) - RIGHT_MARGIN) // the content, right of the handle
    const viewed = e.props.view?.agentId ?? null // the agent the person has open in the main view
    const rows = Math.max(MIN_ROWS + 6, e.props.scroll.bodyRows)
    const now = await $.clock.now()
    const all = await read($, agents)
    const act = await read($, activity)
    const tok = await read($, tokens)
    const id = await read($, viewing)
    const agent = id ? all.find(a => a.id === id) : undefined
    viewingId = agent ? agent.id : null
    const runningCount = all.filter(a => a.status === 'running').length
    const doneCount = all.length - runningCount
    const hint = (text: string) => <Text dimColor wrap="truncate-end">{text}</Text>
    const alertOf = (a: Agent) => (tok[a.id]?.truncated ? `max_tokens ×${tok[a.id]!.truncated}` : '')
    // A running agent's mark, spinning on the surface's clock where it has one; a still mark elsewhere.
    const markOf = (a: Agent, pad: string) => {
      const l = look(a.status)
      return Client && a.status === 'running' && a.seenRunning && cfg.motion ? (
        <Client key={`mark-${a.id}`} module="./live.tsx" props={{ since: a.firstSeen, now, pad, detail: '', alert: '', motion: true, clockOnly: false, markOnly: true }} />
      ) : (
        <Text color={l.color} dimColor={l.dim}>{`${pad}${l.mark} `}</Text>
      )
    }
    const clock = (a: Agent) =>
      Client && a.status === 'running' && a.seenRunning ? (
        <Client key={`clock-${a.id}`} module="./live.tsx" props={{ since: a.firstSeen, now, pad: '', detail: '', alert: '', motion: false, clockOnly: true }} />
      ) : (
        <Text dimColor>{elapsed(a, now)}</Text>
      )
    // The first row, clear of the engine's close mark at its end.
    const header = (left: RenderChildren, right: RenderChildren, width = W) => (
      <Box width={width - CLOSE_MARK_COLS} justifyContent="space-between">
        {left}
        {typeof right === 'string' ? <Text dimColor>{right}</Text> : right}
      </Box>
    )
    // A handle on the pane's left edge, halfway down: ▸ hides the pane. Above the prompt there is no edge to hold.
    const withHandle = (body: RenderChildren) =>
      inline ? (
        <Box flexDirection="column" width={W}>
          {body}
        </Box>
      ) : (
      <Box flexDirection="row">
        <Box key="handle" flexDirection="column" width={HANDLE_COLS} flexShrink={0}>
          {Array.from({ length: Math.max(0, Math.floor((rows - HANDLE.length) / 2)) }, () => <Text> </Text>)}
          {HANDLE.map((glyph, i) => (
            <Button
              key={glyph.startsWith('▸') ? 'collapse' : `collapse-${i}`}
              label={glyph}
              plain
              dimColor
              hover={{ color: 'claude', bold: true }}
              onPress={() => foldAway($)}
            />
          ))}
        </Box>
        <Box flexDirection="column" width={W} height={rows}>
          {body}
        </Box>
      </Box>
      )

    // One agent's conversation, as Claude Code draws its own: > the brief, ⏺ replies and tool calls, ⎿ results.
    if (agent) {
      const key = `${agent.id}:${await read($, rev)}:${agent.status}`
      if (transcript.key !== key) {
        const msgs = await $.session.messages({ agentId: agent.id })
        transcript = { key, blocks: Array.isArray(msgs) ? transcriptBlocks(msgs, agent.status !== 'running') : [] }
      }
      const blocks = transcript.blocks
      const open = new Set(await read($, expanded))
      const armed = await read($, confirmStop)
      const savedTop = await read($, scrollTop)
      const top = savedTop === null ? null : Math.min(savedTop, Math.max(0, blocks.length - 1))
      const shown = pickBlocks(blocks, top)
      const newer = top === null ? 0 : blocks.length - top - 1 // blocks after the one at the top
      const used = tok[agent.id]
      const l = look(agent.status)
      const given = givenName(agent)
      const leave = async () => {
        await showList($)
        await openPane($, 'list') // back to the usual size
      }
      const toggle = (k: string) => update($, expanded, list => (list.includes(k) ? list.filter(x => x !== k) : [...list, k]))
      const result = (c: Call) =>
        c.state === 'running' ? [<Text color="claude">{'  ⎿  Running…'}</Text>]
        : c.state === 'stopped' ? [<Text dimColor>{'  ⎿  Interrupted'}</Text>]
        : [
            ...(c.result.length ? c.result : ['(No output)']).map((r, i) => (
              <Text color={c.state === 'error' ? 'error' : undefined} dimColor={c.state !== 'error'} wrap="truncate-end">
                {`${i ? '     ' : '  ⎿  '}${r}`}
              </Text>
            )),
            ...(c.more ? [<Text dimColor>{`     … +${c.more} line${c.more === 1 ? '' : 's'}`}</Text>] : []),
          ]
      const call = (c: Call) => (
        <Box flexDirection="column" flexShrink={0}>
          <Text wrap="truncate-end">
            <Text color={STATE_COLOR[c.state]}>⏺ </Text>
            <Text bold>{c.name}</Text>
            <Text>{c.arg ? `(${c.arg})` : ''}</Text>
          </Text>
          {result(c)}
        </Box>
      )
      const block = (b: Block): RenderElement => {
        if (b.kind === 'prompt') {
          const lines = wrap(b.text.slice(0, PROMPT_LINES * W * 2), W - 2)
          return (
            <Box flexDirection="column" flexShrink={0} marginTop={1}>
              {lines.slice(0, PROMPT_LINES).map((line, i) => (
                <Text dimColor wrap="truncate-end">{`${i ? '  ' : '> '}${line}`}</Text>
              ))}
              {lines.length > PROMPT_LINES ? <Text dimColor>{'  …'}</Text> : null}
            </Box>
          )
        }
        if (b.kind === 'reply') {
          const text = b.text.length > MAX_REPLY ? `${b.text.slice(0, MAX_REPLY)}\n\n… (${b.text.length - MAX_REPLY} more characters)` : b.text
          return (
            <Box flexDirection="row" flexShrink={0} marginTop={1}>
              <Text>⏺ </Text>
              <Box flexDirection="column" width={W - 2}>
                <Markdown text={text} />
              </Box>
            </Box>
          )
        }
        if (b.calls.length === 1) return <Box flexShrink={0} marginTop={1}>{call(b.calls[0]!)}</Box>
        const isOpen = open.has(b.key)
        const opened = lastCalls(b.calls)
        const live = b.calls.find(c => c.state === 'running')
        const failed = b.calls.find(c => c.state === 'error')
        return (
          <Box key={`grp-${b.key}`} flexDirection="column" flexShrink={0} marginTop={1}>
            <Box>
              <Text color={STATE_COLOR[groupState(b.calls)]}>⏺ </Text>
              <Button key={`group-${b.key}`} label={groupSummary(b.calls)} plain hover={{ color: 'claude' }} onPress={() => toggle(b.key)} />
              <Text dimColor>{isOpen ? ' (click to collapse)' : ' (click to expand)'}</Text>
            </Box>
            {isOpen ? (
              <Box flexDirection="column" paddingLeft={2}>
                {opened.hidden ? <Text dimColor>{`… +${opened.hidden} earlier call${opened.hidden === 1 ? '' : 's'}`}</Text> : null}
                {opened.shown.map(call)}
              </Box>
            ) : live ? (
              <Text color="claude" wrap="truncate-end">{`  ⎿  ${live.name}${live.arg ? `(${live.arg})` : ''} · Running…`}</Text>
            ) : failed ? (
              <Text color="error" wrap="truncate-end">{`  ⎿  ${failed.name} failed: ${failed.result[0] ?? ''}`}</Text>
            ) : null}
          </Box>
        )
      }
      const arm = async () => {
        armedAt = await $.clock.now()
        await update($, confirmStop, () => agent.id)
      }
      return withHandle([
        header(
          <Box>
            <Button key="back" label="←" hotkey="b" dimColor onPress={leave} />
            <Text color={l.color} dimColor={l.dim}> ⏺ </Text>
            {given ? <Text bold>{`${given} `}</Text> : null}
            {given && agent.type === DEFAULT_TYPE ? null : <Text bold={!given} dimColor={!!given}>{fit(oneLine(agent.type), 20)}</Text>}
            <Text dimColor={!!given}>
              {given && agent.type === DEFAULT_TYPE
                ? fit(oneLine(agent.description), Math.max(8, W - 42 - cols(given)))
                : `(${fit(oneLine(agent.description), Math.max(8, W - 42 - cols(agent.type) - cols(given)))})`}
            </Text>
          </Box>,
          <Box>
            {clock(agent)}
            {agent.status !== 'running' ? null : armed === agent.id ? (
              <Button key="stop" label="Confirm stop" variant="primary" onPress={() => update($, confirmStop, () => null).then(() => stopAgent($, agent))} />
            ) : (
              <Button key="stop" label="■ Stop" dimColor onPress={arm} />
            )}
          </Box>,
        ),
        <Text wrap="truncate-end">
          <Text dimColor>
            {`  ⎿  ${[l.word, act[agent.id] ? uses(act[agent.id]!.tools) : '', runsOn(agent), viewed === agent.id ? 'also in the main view' : ''].filter(Boolean).join(' · ')}`}
          </Text>
          {alertOf(agent) ? <Text color="error">{` · ${alertOf(agent)}`}</Text> : null}
        </Text>,
        <Text dimColor wrap="truncate-end">
          {used
            ? `     ${fmtTokens(used.input)} in (${fmtTokens(used.cached)} cached) · ${fmtTokens(used.output)} out · context ${fmtTokens(used.context)} · ${used.requests} request${used.requests === 1 ? '' : 's'}`
            : '     no token figures yet'}
        </Text>,
        // Live: the newest blocks, anchored to the bottom (the oldest cut at the top). Scrolled back: from the
        // block at `top` down, so a block taller than the pane shows its start and new blocks do not move it.
        <Box height={rows - 5} flexDirection="column" justifyContent={top === null ? 'flex-end' : 'flex-start'} overflow="hidden">
          {shown.length ? shown.map(block) : <Text dimColor>Its conversation is not available yet.</Text>}
        </Box>,
        <Text> </Text>,
        <Box width={W} justifyContent="space-between">
          <Box>
            <Button key="older" label="▲" hotkey="k" dimColor onPress={() => update($, scrollTop, v => Math.max(0, (v ?? blocks.length - 1) - 1))} />
            <Button
              key="newer"
              label="▼"
              hotkey="j"
              dimColor
              onPress={() => update($, scrollTop, v => (v === null || v + 1 >= blocks.length - 1 ? null : v + 1))}
            />
            {top === null ? (
              <Text color="success"> ● live</Text>
            ) : (
              <Button key="live" label={newer > 0 ? `⇣ ${newer} newer` : '⇣ live'} onPress={() => update($, scrollTop, () => null)} />
            )}
          </Box>
          {hint(e.props.isFocused ? 'b back · k/j scroll · esc to prompt ' : 'click here for keys b/k/j ')}
        </Box>,
      ])
    }

    // The list, a roster: an agent a row, its columns lined up down the pane: its mark, the name it was given
    // (where any agent has one), its task, what it is doing now or how it ended, its tool count, its tokens
    // and its clock. Finished agents keep their rows under the running ones.
    const shown = visibleAgents(all, cfg.keepFinished)
    const named = nameColumn(shown)
    const model = sharedModel(shown)
    const hidingDone = await read($, hideDone)
    const { running, finished } = arrange(shown, hidingDone)
    const goTo = async (to: string) => {
      await showList($)
      await update($, viewing, () => to)
      await openPane($, 'conversation', true)
    }
    // A row's name column, `width` wide: the name (cut where the pane is too narrow for it) opens the agent as
    // its task does; a row without one keeps the column's width.
    const nameCell = (a: Agent, width: number) => {
      const name = width > 2 ? fit(givenName(a), width - 2) : ''
      return [
        name ? <Button key={`name-${a.id}`} label={name} plain hover={{ color: 'claude', underline: true }} onPress={() => goTo(a.id)} /> : null,
        width ? <Text>{' '.repeat(width - cols(name))}</Text> : null,
      ]
    }
    // Model loops no agent claims, recently active: a workflow's agents, compaction and memory forks.
    const quiet = Object.entries(await read($, loops)).filter(([, x]) => now - x.lastSeen < LOOP_SHOWN_MS)
    const loopsLine = quiet.length
      ? `⏺ ${quiet.length} other model loop${quiet.length === 1 ? '' : 's'} (workflow agents or forks) · ${quiet.reduce((n, [, x]) => n + x.requests, 0)} requests · ${fmtTokens(quiet.reduce((n, [lid]) => n + (tok[lid]?.input ?? 0), 0))} in`
      : ''
    // The latest batch on one time axis (two agents or more, where there is room), and once it has ended,
    // what it came to.
    const batch = latestBatch(all)
    const receipt = batchReceipt(batch, act, tok)
    const receiptLine = receipt ? (
      <Text wrap="truncate-end">
        <Text color={receipt.failed ? 'error' : 'success'}>{receipt.failed ? '✗ ' : '✓ '}</Text>
        <Text dimColor>{receipt.text}</Text>
      </Text>
    ) : null
    // A lane is labelled by the agent's name alone, the list above saying what each one does; without a name,
    // by its task. The label column is as wide as the widest label, within the old bounds; under a list with
    // a name column it is that column, so a lane's bar starts where the tasks do.
    const laneLabel = (a: Agent) => givenName(a) || oneLine(a.description || a.type)
    const lanesMax = Math.min(MAX_LANES, Math.floor(rows / 3))
    const nameCols = Math.min(30, Math.floor(W * 0.38), Math.max(0, ...batch.slice(-lanesMax).map(a => cols(laneLabel(a)))) + (shown.some(a => givenName(a)) ? 1 : 0))
    const barCols = W - 2 - nameCols - 1 - DUR_COLS
    const onAxis = batch.length >= 2 && barCols >= 8 ? batch.slice(-lanesMax) : []
    const lanes: Lane[] = onAxis.map(a => {
      const l = look(a.status)
      const name = fit(laneLabel(a), nameCols)
      return {
        name: name + ' '.repeat(Math.max(0, nameCols - cols(name))), mark: l.mark, color: l.color ?? '', dim: !!l.dim,
        from: a.firstSeen, to: a.status === 'running' ? null : (a.endedAt ?? a.firstSeen),
      }
    })
    const axisTitle = ` timeline${onAxis.length < batch.length ? ` · latest ${onAxis.length} of ${batch.length}` : ''} `
    const axis = lanes.length ? (
      <Box flexDirection="column" flexShrink={0} marginTop={1}>
        <Text dimColor wrap="truncate-end">{`──${axisTitle}${'─'.repeat(Math.max(0, W - 2 - axisTitle.length))}`}</Text>
        {Client ? (
          <Client key="lanes" module="./lanes.tsx" props={{ lanes, now, bar: barCols }} />
        ) : (
          laneRows(lanes, now, barCols).map((g, i) => (
            <Text wrap="truncate-end">
              <Text color={lanes[i]!.color || undefined} dimColor={lanes[i]!.dim}>{`${lanes[i]!.mark} `}</Text>
              <Text>{lanes[i]!.name}</Text>
              <Text dimColor>{` ${'·'.repeat(g.before)}`}</Text>
              <Text color={lanes[i]!.color || undefined} dimColor={lanes[i]!.dim}>{'━'.repeat(g.bar)}</Text>
              <Text dimColor>{`${'·'.repeat(g.after)}${fmtDuration(g.ms).padStart(DUR_COLS)}`}</Text>
            </Text>
          ))
        )}
        {receiptLine}
      </Box>
    ) : receiptLine ? (
      <Box flexShrink={0} marginTop={1}>
        {receiptLine}
      </Box>
    ) : null
    const heading = (
      <Text>
        <Text color="claude">✻ </Text>
        <Text bold>Agents</Text>
        {model ? <Text dimColor>{` · ${model}`}</Text> : null}
      </Text>
    )
    // One agent's row, `width` wide, in the columns `c`: its cells add up to `width`, and the row is one line
    // high whatever a terminal makes of a character this module miscounts. `beneath`: the docked list, where a
    // row may have a line under it: what a running agent is doing where there is no column for it, and what
    // cannot wait (the main view shows it; a response was cut). The summary above the prompt has no rows to spare.
    type Note = { text: string; color?: string }
    const rosterRow = (a: Agent, depth: number, width: number, c: ReturnType<typeof rosterColumns>, beneath: boolean): RenderChildren[] => {
      const pad = ' '.repeat(Math.min(2 * depth, c.task - MIN_TASK + 2)) // a child, indented while the task keeps 6 columns
      const l = look(a.status)
      const live = a.status === 'running'
      const doing = act[a.id]
      const used = tok[a.id]
      const room = c.task - cols(pad)
      const task = fit(taskOf(a, room), room - 2)
      const own = model ? '' : runsOn(a) // said on the row only when the agents' models differ
      const alert: Note[] = alertOf(a) ? [{ text: alertOf(a), color: 'error' }] : []
      const flags: Note[] = [...(viewed === a.id ? [{ text: '◂ main view', color: 'claude' }] : []), ...alert]
      // What it is doing now, or how it ended.
      const state: Note = live
        ? { text: [own, doing?.text ?? ''].filter(Boolean).join(' · ') }
        : { text: [l.word.toLowerCase(), own].filter(Boolean).join(' · '), ...(a.status === 'failed' && { color: 'error' }) }
      const cut = (notes: readonly Note[], max: number) => {
        let left = max
        return notes.filter(n => n.text).flatMap((n, i) => {
          const text = left > 3 ? fit(`${i ? ' · ' : ''}${n.text}`, left) : ''
          left -= cols(text)
          return text ? [<Text color={n.color} dimColor={!n.color}>{text}</Text>] : []
        }).concat(<Text>{' '.repeat(Math.max(0, left))}</Text>)
      }
      const n = doing?.tools ?? 0
      const count = n ? `${n > 9_999 ? `${Math.floor(n / 1000)}k` : n} tool${n === 1 ? '' : 's'}` : ''
      const countCell = n ? `${count.slice(0, count.indexOf(' ')).padStart(c.tools - 6)} ${n === 1 ? 'tool ' : 'tools'}` : ''
      const lines: RenderChildren[] = [
        <Box key={`row-${a.id}`} width={width} height={1} overflow="hidden">
          {markOf(a, pad)}
          {nameCell(a, c.name)}
          <Button key={`agent-${a.id}`} label={task} plain dimColor={!!givenName(a) || !live} hover={{ color: 'claude', underline: true }} onPress={() => goTo(a.id)} />
          <Text>{' '.repeat(Math.max(0, room - cols(task)))}</Text>
          {c.doing ? cut(beneath ? [state] : [state, ...alert], c.doing - 1).concat(<Text> </Text>) : null}
          {c.tools ? <Text dimColor>{countCell.padStart(c.tools)}</Text> : null}
          {c.tokens ? <Text dimColor>{(used ? fmtTokens(used.input + used.output) : '').padStart(c.tokens)}</Text> : null}
          <Box width={CLOCK_COLS} flexShrink={0} justifyContent="flex-end">
            {clock(a)}
          </Box>
        </Box>,
      ]
      if (beneath) {
        const said: Note[] = [...flags, ...(!c.doing && live ? [{ text: [state.text, n > 1 || !state.text ? count : ''].filter(Boolean).join(' · ') }] : [])].filter(x => x.text)
        const lead = `${pad}  ⎿ `
        if (said.length) lines.push(<Box key={`doing-${a.id}`} width={width} height={1} overflow="hidden"><Text dimColor>{lead}</Text>{cut(said, width - cols(lead))}</Box>)
      }
      return lines
    }
    const columnsFor = (rowsOf: readonly { agent: Agent; depth: number }[], width: number, beneath: boolean) =>
      rosterColumns(width, cols(named(shown[0] ?? ({} as Agent))), Math.max(0, ...rowsOf.map(r => cols(taskOf(r.agent, width)) + 2 * r.depth)), beneath)
    const counts = <Box key="counts">
      <Text dimColor>{runningCount ? `${runningCount} running` : ''}</Text>
      <Text dimColor>{runningCount && doneCount ? ' · ' : ''}</Text>
      {doneCount ? (
        <Button key="toggle-done" label={hidingDone ? `${doneCount} done (show)` : `${doneCount} done`} plain dimColor hover={{ color: 'claude', underline: true }} onPress={() => update($, hideDone, v => !v)} />
      ) : null}
    </Box>

    // Above the prompt (no fullscreen to dock in): a summary of at most INLINE_ROWS rows, in the roster's
    // columns: the running agents, then the finished ones while there are rows for them.
    if (inline) {
      const Wc = Math.min(W, INLINE_MAX)
      const live = all.filter(a => a.status === 'running') // a finished parent's running children too
      const ended = hidingDone ? [] : shown.filter(a => a.status !== 'running')
      const SHOW = INLINE_ROWS - 3
      const listed = [...live, ...ended].slice(0, SHOW).map(agent => ({ agent, depth: 0 }))
      const c = columnsFor(listed, Wc, false)
      const moreLive = Math.max(0, live.length - SHOW)
      const moreEnded = hidingDone ? 0 : doneCount - (listed.length - Math.min(live.length, SHOW)) // of all that finished, as the header counts them
      const more = [moreLive ? `+${moreLive} more running` : '', moreEnded ? `+${moreEnded} more done` : ''].filter(Boolean).join(' · ')
      return (
        <Box flexDirection="column" width={W}>
          {header(
            heading,
            <Box>
              {counts}
              <Text> </Text>
              <Button key="collapse" label="▾ hide" dimColor onPress={() => foldAway($)} />
            </Box>,
            Wc,
          )}
          {listed.flatMap(r => rosterRow(r.agent, 0, Wc, c, false))}
          {more ? <Text dimColor>{`  ${more}`}</Text> : null}
          {receiptLine ?? (loopsLine ? <Text dimColor wrap="truncate-end">{loopsLine.replace('⏺ ', '')}</Text> : null)}
          {shown.length ? null : <Text dimColor>No agents yet.</Text>}
        </Box>
      )
    }
    const listed = [...running, ...finished].flatMap(g => [{ agent: g.agent, depth: 0 }, ...g.kids])
    const c = columnsFor(listed, W, true)
    return withHandle(
      <Box flexDirection="column" height={rows} justifyContent="space-between">
        <Box flexDirection="column" flexShrink={1} overflow="hidden">
          {header(heading, counts)}
          {shown.length ? null : <Text dimColor>No agents yet. They show here while they run.</Text>}
          {listed.length ? (
            <Box flexDirection="column" marginTop={1}>
              {listed.flatMap(r => rosterRow(r.agent, r.depth, W, c, true))}
            </Box>
          ) : null}
          {loopsLine ? (
            <Box marginTop={1}>
              <Text dimColor wrap="truncate-end">{loopsLine}</Text>
            </Box>
          ) : null}
        </Box>
        <Box flexDirection="column" flexShrink={0}>
          {axis}
          {hint(shown.length ? `click an agent to open it${doneCount ? ' · click "done" to hide finished ones' : ''}` : '')}
        </Box>
      </Box>,
    )
  })

  // Folded: a tab at the right edge above the prompt, with the agents' counts, brings the pane back.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    isFullscreen = e.viewport?.isFullscreen ?? isFullscreen
    if (e.props.hasSurvey || e.surface === 'desktop') return next(e)
    const { Box, Button } = $.ui.resolve(e)
    // What the plugins beneath drew stays. Never hand the band itself back: it would not be drawn again
    // when the tab comes or goes.
    const below = await next(e).catch(() => null)
    if (!(await read($, tab))) return <Box flexDirection="column">{below}</Box>
    const all = await read($, agents)
    const count = (s: string) => all.filter(a => a.status === s).length
    const running = count('running')
    const label = [
      '◂ Agents',
      running ? `${look('running').mark} ${running}` : '',
      ...['completed', 'failed', 'killed'].map(s => (count(s) ? `${look(s).mark} ${count(s)}` : '')),
    ].filter(Boolean).join(' ')
    return (
      <Box flexDirection="column">
        {below}
        <Box justifyContent="flex-end" paddingRight={BAND_RIGHT_PAD}>
          <Button key="agents-tab" label={label} dimColor onPress={() => unfold($)} />
        </Box>
      </Box>
    )
  })
}

files.hooks/draw.ts:
// Pure name-drawing logic: no engine calls, so it is unit-tested with plain node.

export type Category = {
  key: string;
  subagent_types: string[];
  keywords: string[];
  names: string[];
  /** Agent types the user's names file routes here (`for`): they win before keywords are read. */
  first?: string[];
  /** Names the user added to this pool, when it also holds others: they get FAVOUR of the draws. */
  favoured?: string[];
};
export type Pool = { categories: Category[] };

/** Roles that say nothing about the task: their description's keywords decide first. */
export const GENERIC_ROLES = ['general-purpose', 'worker'];
/** What the Agent tool runs when `subagent_type` is omitted. */
const DEFAULT_ROLE = 'general-purpose';
const FALLBACK = 'default';
/**
 * The share of draws that go to the user's added names while one is free. Without it, two
 * added names in a pool of thirty-odd would name about one agent in eighteen.
 */
export const FAVOUR = 0.5;

function byType(pool: Pool, role: string): string | undefined {
  const r = role.trim().toLowerCase();
  return pool.categories.find(c => c.subagent_types.some(t => t.toLowerCase() === r))?.key;
}

function byKeyword(pool: Pool, text: string): string | undefined {
  const t = text.toLowerCase();
  let best: string | undefined;
  let bestHits = 0;
  for (const c of pool.categories) {
    const hits = c.keywords.filter(k => t.includes(k)).length;
    if (hits > bestHits) { best = c.key; bestHits = hits; } // strict >: ties keep the earlier category
  }
  return best;
}

/**
 * Category for one dispatch: a valid `theme` pins it; then a user's set naming this role;
 * otherwise a specific role wins, a generic role defers to description keywords, and the
 * default pool catches the rest.
 * Mirrors the retired Python package's resolve_for_hook (named-subagents 0.7.2).
 */
export function categoryFor(pool: Pool, subagentType?: string, description?: string, theme = 'auto'): string {
  if (theme !== 'auto' && pool.categories.some(c => c.key === theme)) return theme;
  const role = subagentType ?? DEFAULT_ROLE;
  const r = role.trim().toLowerCase();
  const mine = pool.categories.find(c => c.first?.some(t => t.toLowerCase() === r));
  if (mine) return mine.key; // the user said which agents this pool is for
  const fromType = byType(pool, role);
  const fromTask = description ? byKeyword(pool, description) : undefined;
  if (GENERIC_ROLES.includes(role.trim().toLowerCase())) return fromTask ?? fromType ?? FALLBACK;
  return fromType ?? fromTask ?? FALLBACK;
}

/**
 * A name from `category` not in `taken` (case-insensitive). The pool's favoured names get
 * FAVOUR of the draws while one is free. An exhausted category spills to the default pool,
 * then to any free name; with all taken, a numbered suffix.
 */
export function drawName(pool: Pool, category: string, taken: Iterable<string>, rand: () => number): string {
  const used = new Set([...taken].map(n => n.toLowerCase()));
  const free = (names: string[]) => names.filter(n => !used.has(n.toLowerCase()));
  const home = pool.categories.find(c => c.key === category) ?? pool.categories.find(c => c.key === FALLBACK);
  const mine = free(home?.favoured ?? []);
  if (mine.length && rand() < FAVOUR) return mine[Math.min(mine.length - 1, Math.floor(rand() * mine.length))]!;
  const tiers = [home?.names ?? [], pool.categories.find(c => c.key === FALLBACK)?.names ?? [], pool.categories.flatMap(c => c.names)];
  for (const tier of tiers) {
    const f = free(tier);
    const pick = f[Math.min(f.length - 1, Math.floor(rand() * f.length))];
    if (pick !== undefined) return pick;
  }
  const base = home?.names[0] ?? pool.categories.find(c => c.names.length)?.names[0] ?? 'Agent';
  for (let n = 2; ; n++) if (!used.has(`${base}-${n}`.toLowerCase())) return `${base}-${n}`;
}

export type PickInput = {
  subagentType?: string;
  description?: string;
  theme?: string;
  taken: Iterable<string>;
  rand: () => number;
};

export function pickName(pool: Pool, i: PickInput): { name: string; category: string } {
  const category = categoryFor(pool, i.subagentType, i.description, i.theme);
  return { name: drawName(pool, category, i.taken, i.rand), category };
}

files.hooks/custom.ts:
// Custom names: pure logic, no engine calls, so it is unit-tested with plain node.
//
// A names file (and the install screen's `names` list) is parsed into a Custom, and one or
// more Customs are layered onto the built-in pool: user file, then project file, then the
// install screen. `/names` edits the user file through the functions at the bottom.

import type { Category, Pool } from './draw.ts';

/** The Agent tool's own rule for `name`; a call carrying anything else is refused. */
export const NAME_RE = /^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$/;
const MAX_LEN = 60; // leaves room for the "-2" suffix of an exhausted pool
const FALLBACK = 'default';

/**
 * Makes a typed name one the Agent tool accepts: accents dropped, apostrophes dropped,
 * words joined ("Mary Shelley" -> "MaryShelley"). Undefined when nothing usable is left.
 */
export function cleanName(raw: string): string | undefined {
  if (/[\u0000-\u001f\u007f-\u009f]/.test(raw.trim())) return undefined; // no name holds a control character; not worth salvaging
  const parts = raw.normalize('NFKD').replace(/[̀-ͯ]/g, '').replace(/['’`]/g, '')
    .split(/[^A-Za-z0-9_-]+/).filter(p => p !== '');
  const joined = parts.map((p, i) => (i === 0 ? p : p.charAt(0).toUpperCase() + p.slice(1))).join('')
    .replace(/^[_-]+/, '').slice(0, MAX_LEN);
  return NAME_RE.test(joined) ? joined : undefined;
}

export type CustomSet = { names: string[]; for: string[]; keywords: string[]; replace: boolean };
export type Custom = {
  /** Leave out everything layered before this (the built-in names included). */
  only: boolean;
  /** The pool every agent draws from; absent or "auto" picks by agent type and task. */
  use?: string;
  /** Names that join every pool except the sets the files define themselves. */
  names: string[];
  /** Names never drawn. */
  remove: string[];
  /** Old name -> new name. */
  rename: Record<string, string>;
  /** A new pool, or more names (or with `replace`, other names) for a built-in one. */
  sets: Record<string, CustomSet>;
};
export type Parsed = { custom: Custom; problems: string[]; cleaned: string[] };

export const emptyCustom = (): Custom => ({ only: false, names: [], remove: [], rename: {}, sets: {} });

const lower = (s: string) => s.toLowerCase();
function uniq(names: string[]): string[] {
  const seen = new Set<string>();
  return names.filter(n => !seen.has(lower(n)) && !!seen.add(lower(n)));
}
/**
 * A names file is untrusted input (a project's arrives with the repository), so what is read
 * from one is bounded: the file's size, how many names, sets and routes it may hold, and how
 * many problems are kept to report.
 */
export const LIMITS = { fileChars: 256 * 1024, names: 2000, sets: 100, routes: 200, problems: 20 } as const;

/**
 * Text safe to show in a terminal: control characters (escape sequences among them) and the
 * characters that reorder text become "?". Newlines stay.
 */
export const printable = (s: string) => s.replace(/[\u0000-\u0009\u000b-\u001f\u007f-\u009f\u200e\u200f\u202a-\u202e\u2066-\u2069]/g, '?');

/** A bad entry as a problem quotes it: short, on one line, and printable, whatever it held. */
const quote = (v: unknown) => {
  const t = printable(typeof v === 'string' ? v : JSON.stringify(v) ?? String(v)).replace(/\s+/g, ' ').trim();
  return `"${t.length > 40 ? `${t.slice(0, 40)}…` : t}"`;
};
/** At most LIMITS.problems lines, each printable; the rest are counted. */
function bounded(lines: string[], label: string, what: string): string[] {
  const safe = lines.slice(0, LIMITS.problems).map(t => printable(t).replace(/\n/g, ' '));
  return lines.length > LIMITS.problems ? [...safe, `${label}: and ${lines.length - LIMITS.problems} more ${what}`] : safe;
}
const isRecord = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);

/** A list of names from a JSON array of strings or one comma-separated string (or a list of those). */
function nameList(v: unknown, where: string, p: Parsed): string[] {
  let raw = typeof v === 'string' ? v.split(',') : Array.isArray(v) ? v.flatMap(x => (typeof x === 'string' ? x.split(',') : [x])) : undefined;
  if (raw === undefined) { p.problems.push(`${where} must be a list of names`); return []; }
  if (raw.length > LIMITS.names) { p.problems.push(`${where}: only the first ${LIMITS.names} names are read`); raw = raw.slice(0, LIMITS.names); }
  const out: string[] = [];
  for (const r of raw) {
    if (typeof r !== 'string') { p.problems.push(`${where}: ${quote(r)} is not a name`); continue; }
    if (r.trim() === '') continue;
    const c = cleanName(r);
    if (c === undefined) { p.problems.push(`${where}: ${quote(r)} cannot be a name (letters, digits, _ and - only)`); continue; }
    if (c !== r.trim()) p.cleaned.push(`${quote(r)} -> ${c}`);
    out.push(c);
  }
  return uniq(out);
}

function textList(v: unknown, where: string, p: Parsed): string[] {
  if (!Array.isArray(v) || v.some(x => typeof x !== 'string')) { p.problems.push(`${where} must be a list of strings`); return []; }
  if (v.length > LIMITS.routes) p.problems.push(`${where}: only the first ${LIMITS.routes} entries are read`);
  // Shown by /names and matched against agent types and task text: one printable line each.
  return (v as string[]).slice(0, LIMITS.routes).map(s => printable(s).replace(/\s+/g, ' ').trim().slice(0, 64)).filter(s => s !== '');
}

/** A Custom from an already-parsed JSON value; what is wrong is listed, the rest is kept. */
export function readCustom(value: unknown, rawLabel: string): Parsed {
  const label = printable(rawLabel).replace(/\s+/g, ' ').slice(0, 120);
  const p = readAll(value, label);
  return { custom: p.custom, problems: bounded(p.problems, label, 'problems'), cleaned: bounded(p.cleaned, label, 'adjusted names') };
}

function readAll(value: unknown, label: string): Parsed {
  const p: Parsed = { custom: emptyCustom(), problems: [], cleaned: [] };
  if (!isRecord(value)) { p.problems.push(`${label}: expected a JSON object`); return p; }
  const c = p.custom;
  for (const [key, v] of Object.entries(value)) {
    const where = `${label}: ${key}`;
    if (key === 'only') { if (typeof v === 'boolean') c.only = v; else p.problems.push(`${where} must be true or false`); }
    else if (key === 'use') { if (typeof v === 'string' && NAME_RE.test(v.trim())) c.use = v.trim(); else p.problems.push(`${where} must be a pool's name`); }
    else if (key === 'names') c.names = nameList(v, where, p);
    else if (key === 'remove') c.remove = nameList(v, where, p);
    else if (key === 'rename') {
      if (!isRecord(v)) { p.problems.push(`${where} must map old names to new ones`); continue; }
      const pairs = Object.entries(v);
      if (pairs.length > LIMITS.names) p.problems.push(`${where}: only the first ${LIMITS.names} names are read`);
      for (const [from, to] of pairs.slice(0, LIMITS.names)) {
        const [f] = nameList([from], where, p);
        const [t] = typeof to === 'string' ? nameList([to], where, p) : [];
        if (f !== undefined && t !== undefined) c.rename[f] = t;
        else if (typeof to !== 'string') p.problems.push(`${where}: ${quote(from)} needs a new name`);
      }
    } else if (key === 'sets') {
      if (!isRecord(v)) { p.problems.push(`${where} must map a set's name to its names`); continue; }
      for (const [setKey, s] of Object.entries(v)) {
        if (Object.keys(c.sets).length >= LIMITS.sets) { p.problems.push(`${where}: only the first ${LIMITS.sets} sets are read`); break; }
        const at = `${label}: sets.${setKey.slice(0, 40)}`; // used only once the key has passed NAME_RE
        if (!NAME_RE.test(setKey)) { p.problems.push(`${label}: sets: ${quote(setKey)} cannot name a set (letters, digits, _ and - only)`); continue; }
        const set: CustomSet = { names: [], for: [], keywords: [], replace: false };
        if (Array.isArray(s) || typeof s === 'string') set.names = nameList(s, at, p); // shorthand: just the names
        else if (isRecord(s)) {
          for (const [k, sv] of Object.entries(s)) {
            if (k === 'names') set.names = nameList(sv, `${at}.names`, p);
            else if (k === 'for') set.for = textList(sv, `${at}.for`, p);
            else if (k === 'keywords') set.keywords = textList(sv, `${at}.keywords`, p).map(lower);
            else if (k === 'replace') { if (typeof sv === 'boolean') set.replace = sv; else p.problems.push(`${at}.replace must be true or false`); }
            else p.problems.push(`${at}: unknown key ${quote(k)} ignored`);
          }
        } else { p.problems.push(`${at} must be a list of names or an object`); continue; }
        c.sets[setKey] = set;
      }
    } else p.problems.push(`${label}: unknown key ${quote(key)} ignored`);
  }
  return p;
}

/** A Custom from a names file's text. Invalid JSON is one problem and an empty Custom. */
export function parseCustom(text: string, label: string): Parsed {
  if (text.length > LIMITS.fileChars) return tooLarge(label);
  let value: unknown;
  try { value = JSON.parse(text); } catch (err) {
    // The engine's message quotes the head of what it could not parse, and a project's file may be a
    // symlink to anything: only the position is kept, never the text.
    const where = /position (\d+)/.exec(String(err instanceof Error ? err.message : err))?.[1];
    return { custom: emptyCustom(), problems: [`${printable(label).slice(0, 120)}: not valid JSON${where ? ` (at character ${where})` : ''}`], cleaned: [] };
  }
  return readCustom(value, label);
}

const tooLarge = (label: string): Parsed => ({ custom: emptyCustom(), problems: [`${printable(label).slice(0, 120)}: too large (over ${LIMITS.fileChars / 1024} KB); it was not read`], cleaned: [] });

/** The file's text for a Custom: only the keys that say something. */
export function serializeCustom(c: Custom): string {
  const out: Record<string, unknown> = {};
  if (c.only) out.only = true;
  if (c.use !== undefined) out.use = c.use;
  if (c.names.length) out.names = c.names;
  if (c.remove.length) out.remove = c.remove;
  if (Object.keys(c.rename).length) out.rename = c.rename;
  const sets: Record<string, unknown> = {};
  for (const [k, s] of Object.entries(c.sets)) {
    sets[k] = { names: s.names, ...(s.for.length ? { for: s.for } : {}), ...(s.keywords.length ? { keywords: s.keywords } : {}), ...(s.replace ? { replace: true } : {}) };
  }
  if (Object.keys(sets).length) out.sets = sets;
  return JSON.stringify(out, null, 2) + '\n';
}

export type Layer = { label: string; custom: Custom };
export type Applied = { pool: Pool; use?: string; problems: string[] };

const findCat = (cats: Category[], key: string) => cats.find(c => lower(c.key) === lower(key));

/**
 * The pool after each layer in turn. Within a layer: `only` empties what came before, sets
 * are defined (new ones go first; a set's `for` wins for those agent types), flat names join
 * every pool that is not a file-defined set, then `rename` and then `remove` apply to everything.
 * Names added to a pool that keeps other names are marked `favoured`, so they are drawn often.
 * A result with no names at all falls back to `base`, with a problem saying so.
 */
export function applyCustom(base: Pool, layers: Layer[]): Applied {
  let cats: Category[] = base.categories.map(c => ({ ...c, subagent_types: [...c.subagent_types], keywords: [...c.keywords], names: [...c.names] }));
  const own = new Set<string>(); // keys of the sets the layers created
  const problems: string[] = [];
  let use: string | undefined;
  let useFrom = '';
  for (const { label, custom: c } of layers) {
    if (c.only) { cats = []; own.clear(); }
    const fresh: Category[] = [];
    for (const [key, s] of Object.entries(c.sets)) {
      let cat = findCat(cats, key) ?? findCat(fresh, key);
      if (!cat) { cat = { key, subagent_types: [], keywords: [], names: [] }; fresh.push(cat); own.add(lower(key)); }
      if (s.for.length) cat.first = [...new Set([...s.for, ...(cat.first ?? [])])];
      if (!own.has(lower(cat.key))) cat.favoured = uniq([...(cat.favoured ?? []), ...s.names]); // added to a built-in pool
      cat.names = uniq([...(s.replace ? [] : cat.names), ...s.names]);
      cat.subagent_types = [...new Set([...s.for, ...cat.subagent_types])];
      cat.keywords = [...new Set([...s.keywords, ...cat.keywords])];
    }
    cats = [...fresh, ...cats];
    if (c.names.length) {
      let targets = cats.filter(k => !own.has(lower(k.key)));
      if (!targets.length) {
        let d = findCat(cats, FALLBACK);
        if (!d) { d = { key: FALLBACK, subagent_types: [], keywords: [], names: [] }; cats.push(d); }
        targets = [d];
      }
      for (const t of targets) { t.names = uniq([...t.names, ...c.names]); t.favoured = uniq([...(t.favoured ?? []), ...c.names]); }
    }
    const renames = Object.entries(c.rename);
    if (renames.length) {
      const to = new Map(renames.map(([f, t]) => [lower(f), t]));
      for (const k of cats) { k.names = uniq(k.names.map(n => to.get(lower(n)) ?? n)); if (k.favoured) k.favoured = uniq(k.favoured.map(n => to.get(lower(n)) ?? n)); }
    }
    if (c.remove.length) { // after rename, so a name can be hidden by what it is called now
      const gone = new Set(c.remove.map(lower));
      for (const k of cats) k.names = k.names.filter(n => !gone.has(lower(n)));
    }
    if (c.use !== undefined) { use = lower(c.use) === 'auto' ? undefined : c.use; useFrom = label; }
  }
  for (const k of cats) { // favoured: the added names still in the pool, and only where the pool holds others too
    const has = new Set(k.names.map(lower));
    const kept = (k.favoured ?? []).filter(n => has.has(lower(n)));
    if (kept.length && kept.length < k.names.length) k.favoured = kept; else delete k.favoured;
  }
  if (!cats.some(k => k.names.length)) {
    problems.push('no names are left after your changes; using the built-in names');
    return { pool: base, problems };
  }
  if (use !== undefined) {
    const hit = findCat(cats, use);
    if (hit) use = hit.key; else { problems.push(`${useFrom}: use names no pool called "${use}"; picking by agent type instead`); use = undefined; }
  }
  return { pool: { categories: cats }, use, problems };
}

// ---- /names: edits to the user's file ----

/** Splits a command's arguments on spaces and commas; quotes keep a name with spaces whole. */
export function tokenize(args: string): string[] {
  const out: string[] = [];
  for (const m of args.matchAll(/"([^"]*)"|'([^']*)'|([^\s,]+)/g)) {
    const t = (m[1] ?? m[2] ?? m[3] ?? '').trim();
    if (t !== '') out.push(t);
  }
  return out;
}

export type Edit = { custom: Custom; lines: string[]; changed: boolean };

function cleanAll(raw: string[], lines: string[]): string[] {
  const p: Parsed = { custom: emptyCustom(), problems: [], cleaned: [] };
  const names = nameList(raw, 'name', p);
  if (p.cleaned.length) lines.push(`Adjusted to fit the name rule: ${p.cleaned.join(', ')}`);
  for (const pr of p.problems) lines.push(pr.replace(/^name: /, 'Skipped: '));
  return names;
}

export const USAGE = [
  '/names                             what is set, and where the files are',
  '/names add Ripley "Mary Shelley"   more names, for every built-in pool',
  '/names remove Sisyphus             never draw this name',
  '/names rename Turing Alan          call one name something else',
  '/names set pirates Kidd Bonny      define a set (a pool of your own); same name again replaces it',
  '/names unset pirates               drop a set',
  '/names use pirates | auto          draw every agent from one pool, or go back to picking by task',
  '/names only on | off               leave out the built-in names',
  '/names import <file>               merge a names file, a JSON list, or one name per line',
  '/names reset                       clear your file (a .bak copy is kept)',
].join('\n');

/**
 * One editing verb applied to the user's Custom. `builtin` is the pool the file is layered
 * on: `use` may name its pools, and `remove` hides its names. Unknown verbs and bad
 * arguments change nothing.
 */
export function editCustom(before: Custom, verb: string, argv: string[], builtin: Pool): Edit {
  const pools = builtin.categories.map(k => k.key);
  const c: Custom = { ...before, names: [...before.names], remove: [...before.remove], rename: { ...before.rename }, sets: Object.fromEntries(Object.entries(before.sets).map(([k, s]) => [k, { ...s, names: [...s.names] }])) };
  const lines: string[] = [];
  const same = (lines2: string[]): Edit => ({ custom: before, lines: lines2, changed: false });
  if (verb === 'add') {
    const names = cleanAll(argv, lines);
    if (!names.length) return same([...lines, 'Usage: /names add Ripley "Mary Shelley"']);
    const added = names.filter(n => !c.names.some(x => lower(x) === lower(n)));
    c.names = uniq([...c.names, ...names]);
    c.remove = c.remove.filter(r => !names.some(n => lower(n) === lower(r)));
    lines.push(added.length ? `Added ${added.join(', ')}.` : 'Already there.');
    if (!c.only) lines.push('Your names get about half of the draws while one is free; /names only on leaves the built-in names out.');
  } else if (verb === 'remove') {
    const names = cleanAll(argv, lines);
    if (!names.length) return same([...lines, 'Usage: /names remove Sisyphus']);
    const isBuiltin = (n: string) => builtin.categories.some(k => k.names.some(x => lower(x) === lower(n)));
    for (const n of names) {
      const mine = c.names.some(x => lower(x) === lower(n)) || Object.values(c.sets).some(s => s.names.some(x => lower(x) === lower(n)));
      c.names = c.names.filter(x => lower(x) !== lower(n));
      for (const s of Object.values(c.sets)) s.names = s.names.filter(x => lower(x) !== lower(n));
      // A name that exists only because of a rename: undo the rename and hide what it was.
      const was = Object.keys(c.rename).filter(f => lower(c.rename[f] ?? '') === lower(n));
      for (const f of was) { delete c.rename[f]; c.remove = uniq([...c.remove, f]); }
      if (mine) lines.push(`Removed ${n} from your names.`);
      if (was.length) lines.push(`${n} was your name for ${was.join(', ')}; that will not be drawn.`);
      if (isBuiltin(n) || (!mine && !was.length)) { c.remove = uniq([...c.remove, n]); lines.push(`${n} will not be drawn.`); }
    }
  } else if (verb === 'rename') {
    const names = cleanAll(argv, lines);
    const [from, to] = names;
    if (from === undefined || to === undefined || names.length !== 2) return same([...lines, 'Usage: /names rename Turing Alan']);
    c.rename[from] = to;
    lines.push(`${from} is now ${to}.`);
  } else if (verb === 'set') {
    const [typed, ...rest] = argv;
    if (typed === undefined || !NAME_RE.test(typed)) return same(["Usage: /names set pirates Kidd Bonny   (the set's name takes letters, digits, _ and - only)"]);
    const key = Object.keys(c.sets).find(k => lower(k) === lower(typed)) ?? typed; // "Pirates" is the set "pirates"
    const names = cleanAll(rest, lines);
    if (!names.length) return same([...lines, `Usage: /names set ${key} Kidd Bonny`]);
    const old = c.sets[key];
    c.sets[key] = { names, for: old?.for ?? [], keywords: old?.keywords ?? [], replace: old?.replace ?? false };
    lines.push(`Set ${key}: ${names.join(', ')}.`, `Use it for every agent with /names use ${key}.`);
  } else if (verb === 'unset') {
    const [key] = argv;
    const hit = key === undefined ? undefined : Object.keys(c.sets).find(k => lower(k) === lower(key));
    if (hit === undefined) return same([`No set called ${key ?? '(nothing)'} in your file.`]);
    delete c.sets[hit];
    if (c.use !== undefined && lower(c.use) === lower(hit)) delete c.use;
    lines.push(`Dropped the set ${hit}.`);
  } else if (verb === 'use') {
    const [key] = argv;
    if (key === undefined) return same(['Usage: /names use pirates   or   /names use auto']);
    if (lower(key) === 'auto') { delete c.use; lines.push('Pools are picked by agent type and task again.'); }
    else {
      const hit = [...Object.keys(c.sets), ...pools].find(k => lower(k) === lower(key));
      if (hit === undefined) return same([`No pool called ${key}. Pools: ${[...Object.keys(c.sets), ...pools].join(', ')}.`]);
      c.use = hit;
      lines.push(`Every agent now draws from ${hit}.`);
    }
  } else if (verb === 'only') {
    const [flag] = argv.map(lower);
    if (flag !== 'on' && flag !== 'off') return same(['Usage: /names only on   or   /names only off']);
    c.only = flag === 'on';
    lines.push(c.only ? 'The built-in names are left out; only yours are drawn.' : 'The built-in names are back.');
  } else return same([USAGE]);
  return { custom: c, lines, changed: serializeCustom(c) !== serializeCustom(before) };
}

/** `incoming` merged into `into`: lists are joined, and so is a set of the same name. */
export function mergeCustom(into: Custom, incoming: Custom): Custom {
  const sets: Record<string, CustomSet> = Object.fromEntries(Object.entries(into.sets).map(([k, s]) => [k, { ...s }]));
  for (const [k, s] of Object.entries(incoming.sets)) {
    const key = Object.keys(sets).find(x => lower(x) === lower(k)) ?? k;
    const old = Object.hasOwn(sets, key) ? sets[key] : undefined; // "constructor" is a set only when the file has it
    sets[key] = old === undefined ? { ...s } : {
      names: uniq([...old.names, ...s.names]), for: [...new Set([...old.for, ...s.for])],
      keywords: [...new Set([...old.keywords, ...s.keywords])], replace: old.replace || s.replace,
    };
  }
  return {
    only: into.only || incoming.only,
    ...(incoming.use ?? into.use) !== undefined ? { use: incoming.use ?? into.use } : {},
    names: uniq([...into.names, ...incoming.names]),
    remove: uniq([...into.remove, ...incoming.remove]),
    rename: { ...into.rename, ...incoming.rename },
    sets,
  };
}

/** What an imported file holds: a names file, a JSON list of names, or one name per line. */
export function parseImport(text: string, label: string): Parsed {
  if (text.length > LIMITS.fileChars) return tooLarge(label);
  let value: unknown;
  try { value = JSON.parse(text); } catch { value = text.split(/\r?\n/); } // audit-allow: fail-loud — not JSON means a plain list, one name per line
  return readCustom(Array.isArray(value) ? { names: value } : value, label);
}

